import React, { useState } from "react";
import { useNavigate, Link } from "react-router-dom";
import "../index.css";

function Login() {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const navigate = useNavigate();

  const handleLogin = (e) => {
    e.preventDefault();

    // Dummy login (replace with API)
    if (email && password) {
      navigate("/dashboard");
    }
  };

  return (
    <div className="form-card">
      <h2 className="form-title">Login</h2>

      <form onSubmit={handleLogin}>
        <div style={{ display: 'flex', alignItems: 'center', marginBottom: '8px' }}>
        <label style={{ minWidth: '80px', marginRight: '10px' }}>Email</label>
        <input
          className="input-field"
          type="email"

          value={email}
          onChange={(e) =>
          setEmail(e.target.value)}
        style={{ flexGrow: 1, margin: 0 }} // New style to make it grow and remove default margin
        />
        </div>

        <div style={{ display: 'flex', alignItems: 'center', marginBottom: '16px' }}> {/* Increased margin for visual break */}
        <label style={{ minWidth: '80px', marginRight: '10px' }}>Password</label>
        <input
          className="input-field"
          type="password"
          value={password}
          onChange={(e) =>
          setPassword(e.target.value)}
        style={{ flexGrow: 1, margin: 0 }} // New style to make it grow and remove default margin
        />
        </div>

        <button className="submit-btn" type="submit">
          Login
        </button>

        <p className="small-text">
          Don't have an account? <Link to="/signup">Sign up</Link>
        </p>
      </form>
    </div>
  );
}

export default Login;
